193: fn parse_rate_limit_window(
194:     headers: &HeaderMap,
195:     used_percent_header: &str,
196:     window_minutes_header: &str,
197:     resets_at_header: &str,
198: ) -> Option<RateLimitWindow> {
199:     let used_percent: Option<f64> = parse_header_f64(headers, used_percent_header);
200: 
201:     used_percent.and_then(|used_percent| {
202:         let window_minutes = parse_header_i64(headers, window_minutes_header);
203:         let resets_at = parse_header_i64(headers, resets_at_header);
204: 
205:         let has_data = used_percent != 0.0
206:             || window_minutes.is_some_and(|minutes| minutes != 0)
207:             || resets_at.is_some();
208: 
209:         has_data.then_some(RateLimitWindow {
210:             used_percent,
211:             window_minutes,
212:             resets_at,
213:         })
214:     })
215: }
